  note = excluded.note, level = excluded.level, tema = excluded.tema, sort = excluded.sort,
  uk = excluded.uk, exuk = excluded.exuk, noteuk = excluded.noteuk,
  en = excluded.en, exen = excluded.exen, noteen = excluded.noteen;

delete from public.pt_words
 where deck_id = 'b2' and updated_at < now();

commit;

select count(*) as слов, count(*) filter (where level = '') as без_уровня,
       count(distinct tema) as тем,
       count(*) filter (where uk <> '') as по_украински,
       count(*) filter (where en <> '') as по_английски
  from public.pt_words where deck_id = 'b2';
